-- StudyHub – Supabase schema (PostgreSQL)
-- Run this in the SQL editor of your Supabase project (or via `supabase db push`).
--
-- Every table mirrors the local SQLite table and adds `rev bigint`, which the
-- trigger below increments on every update. Row Level Security restricts all
-- access to rows with user_id = auth.uid(). Timestamps are ISO-8601 strings
-- generated by the clients (UTC) and stored as text so they compare exactly like
-- in SQLite; `rev` is the server-side version number.

create extension if not exists "pgcrypto";

-- Server-side revision counter -------------------------------------------------
create or replace function public.studyhub_bump_rev()
returns trigger
language plpgsql
as $$
begin
  if tg_op = 'INSERT' then
    new.rev := 1;
  else
    new.rev := coalesce(old.rev, 0) + 1;
  end if;
  -- Server time of the write; clients pull by this cursor so that rows with
  -- older client timestamps (edited offline, synced later) are never missed.
  new.synced_at := now();
  return new;
end;
$$;

-- subjects -----------------------------------------------------------------
create table if not exists public.subjects (
  id uuid primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  created_at text not null,
  updated_at text not null,
  deleted_at text,
  rev bigint not null default 0,
  synced_at timestamptz not null default now(),
  name text not null,
  color text not null default '#3b5bdb',
  teacher text,
  room text,
  sort_order integer not null default 0
);
create index if not exists idx_subjects_user_synced on public.subjects (user_id, synced_at);
drop trigger if exists trg_subjects_rev on public.subjects;
create trigger trg_subjects_rev before insert or update on public.subjects
  for each row execute function public.studyhub_bump_rev();
alter table public.subjects enable row level security;
drop policy if exists "subjects_owner_select" on public.subjects;
drop policy if exists "subjects_owner_insert" on public.subjects;
drop policy if exists "subjects_owner_update" on public.subjects;
create policy "subjects_owner_select" on public.subjects for select using (user_id = auth.uid());
create policy "subjects_owner_insert" on public.subjects for insert with check (user_id = auth.uid());
create policy "subjects_owner_update" on public.subjects for update using (user_id = auth.uid()) with check (user_id = auth.uid());
-- No delete policy: rows are soft-deleted via deleted_at, never removed.

