-- Storage ------------------------------------------------------------------------
-- One bucket per user, named after the user id. The client creates it on first
-- upload; these policies allow exactly that and nothing else.
drop policy if exists "studyhub_bucket_select" on storage.buckets;
drop policy if exists "studyhub_bucket_insert" on storage.buckets;
create policy "studyhub_bucket_select" on storage.buckets for select using (id = auth.uid()::text);
create policy "studyhub_bucket_insert" on storage.buckets for insert with check (id = auth.uid()::text);

drop policy if exists "studyhub_objects_select" on storage.objects;
drop policy if exists "studyhub_objects_insert" on storage.objects;
drop policy if exists "studyhub_objects_update" on storage.objects;
drop policy if exists "studyhub_objects_delete" on storage.objects;
create policy "studyhub_objects_select" on storage.objects for select using (bucket_id = auth.uid()::text);
create policy "studyhub_objects_insert" on storage.objects for insert with check (bucket_id = auth.uid()::text);
create policy "studyhub_objects_update" on storage.objects for update using (bucket_id = auth.uid()::text) with check (bucket_id = auth.uid()::text);
create policy "studyhub_objects_delete" on storage.objects for delete using (bucket_id = auth.uid()::text);
